import Link from 'next/link';

export default function Forbidden() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100vh',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <h1 style={{ fontSize: '3rem', marginBottom: '1rem', color: '#e11d48' }}>403 Forbidden</h1>
      <p style={{ fontSize: '1.25rem', marginBottom: '2rem', color: '#4b5563' }}>
        You do not have permission to access this resource.
      </p>
      <Link 
        href="/"
        style={{
          padding: '0.75rem 1.5rem',
          backgroundColor: '#000',
          color: '#fff',
          textDecoration: 'none',
          borderRadius: '0.375rem',
          fontWeight: 500
        }}
      >
        Return Home
      </Link>
    </div>
  );
}

import { verifyAdmin } from '../lib/auth';
import { forbidden } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '1rem' }}>Admin Dashboard</h1>
      <div style={{ 
        padding: '1.5rem', 
        border: '1px solid #e5e7eb', 
        borderRadius: '0.5rem',
        backgroundColor: '#f9fafb'
      }}>
        <p style={{ fontSize: '1.1rem' }}>Welcome back, <strong>{session?.name}</strong>!</p>
        <p style={{ color: '#059669', marginTop: '0.5rem' }}>✓ You have admin privileges.</p>

        <div style={{ marginTop: '2rem' }}>
          <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '0.5rem' }}>Restricted Controls</h2>
          <button style={{
            padding: '0.5rem 1rem',
            backgroundColor: '#2563eb',
            color: 'white',
            border: 'none',
            borderRadius: '0.25rem',
            cursor: 'pointer'
          }}>
            Manage Users
          </button>
        </div>
      </div>
    </div>
  );
}

